import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { supabase } from '../lib/supabase';
import { DollarSign, ShoppingCart, Package, TrendingUp, Clock, Users, BarChart3, Receipt, RotateCcw, Percent, CheckCircle, AlertTriangle, Shield, Tag, AlertOctagon, RefreshCw, FileText } from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const PRICING = [
  { minStores: 1, maxStores: 1, monthly: 150, label: '1 Store' },
  { minStores: 2, maxStores: 2, monthly: 250, label: '2 Stores' },
  { minStores: 3, maxStores: 3, monthly: 580, label: '3 Stores' },
];

export default function Dashboard() {
  const { staff, subscriptionStatus, trialDaysLeft, isLocked, availableStores, storeId, checkSubscription } = useAuth();
  const navigate = useNavigate();

  const storeCount = availableStores?.length || 0;
  const currentStore = availableStores.find(s => s.id === storeId);
  const plan = PRICING.find(p => storeCount >= p.minStores && storeCount <= p.maxStores);
  const subscriptionPlan = currentStore?.subscription_plan;

  const [expiringProducts, setExpiringProducts] = useState([]);
  const [lowStockProducts, setLowStockProducts] = useState([]);
  const [lowStockThreshold, setLowStockThreshold] = useState(5);
  const [activeLaybyCount, setActiveLaybyCount] = useState(0);
  const [refreshing, setRefreshing] = useState(false);

  // Real KPI numbers
  const [todaySales, setTodaySales] = useState(0);
  const [monthSales, setMonthSales] = useState(0);
  const [totalTransactions, setTotalTransactions] = useState(0);

  // Foolproof direct localStorage read for sales
  const fetchAllData = useCallback(async () => {
    if (!storeId) return;
    setRefreshing(true);
    try {
      // Read sales directly from localStorage
      const rawSales = localStorage.getItem('bwanali_sales');
      let salesArray = rawSales ? JSON.parse(rawSales) : [];
      // Filter by store and not returned
      salesArray = salesArray.filter(s => s.store_id === storeId && !s.returned);

      const todayStart = new Date(); todayStart.setHours(0,0,0,0);
      const todayEnd = new Date(); todayEnd.setHours(23,59,59,999);
      const monthStart = new Date(); monthStart.setDate(1); monthStart.setHours(0,0,0,0);

      const todayFiltered = salesArray.filter(s => { const d = new Date(s.created_at); return d >= todayStart && d <= todayEnd; });
      const monthFiltered = salesArray.filter(s => { const d = new Date(s.created_at); return d >= monthStart && d <= todayEnd; });

      setTodaySales(todayFiltered.reduce((sum, s) => sum + (s.total_amount || 0), 0));
      setMonthSales(monthFiltered.reduce((sum, s) => sum + (s.total_amount || 0), 0));
      setTotalTransactions(salesArray.length);

      // Products (low stock & expiring) - use mock but careful
      const { data: productsData } = await supabase.from('products').select('*').eq('store_id', storeId).eq('is_active', true);
      const products = productsData?.data || productsData || [];
      setLowStockProducts(products.filter(p => (p.stock_quantity || 0) <= lowStockThreshold));
      const expiring = products.filter(p => p.expiry_date &&
        new Date(p.expiry_date) <= new Date(Date.now() + 7*24*60*60*1000) &&
        new Date(p.expiry_date) >= new Date());
      setExpiringProducts(expiring.map(p => ({ ...p, daysLeft: Math.ceil((new Date(p.expiry_date) - new Date()) / (1000*60*60*24)) })));

      // Layby count
      const { data: laybyData } = await supabase
        .from('laybys')
        .select('*', { count: 'exact', head: true })
        .eq('store_id', storeId)
        .eq('status', 'active');
      setActiveLaybyCount(laybyData?.count || 0);
    } catch (err) {
      console.error(err);
    } finally {
      setRefreshing(false);
    }
  }, [storeId, lowStockThreshold]);

  useEffect(() => {
    supabase.from('company_settings').select('low_stock_threshold').eq('store_id', storeId).single()
      .then(({ data }) => { if (data?.low_stock_threshold) setLowStockThreshold(Number(data.low_stock_threshold)); });
  }, [storeId]);

  useEffect(() => { fetchAllData(); }, [fetchAllData]);

  const handleAddDiscount = (product) => {
    navigate(`/app/discounts?productId=${product.id}&productName=${encodeURIComponent(product.name)}`);
  };

  const salesChartData = [
    { day: 'Mon', sales: 1240 }, { day: 'Tue', sales: 1890 }, { day: 'Wed', sales: 980 },
    { day: 'Thu', sales: 2340 }, { day: 'Fri', sales: 3120 }, { day: 'Sat', sales: 2890 }, { day: 'Sun', sales: 1560 },
  ];

  const currency = 'K';

  return (
    <div className="p-4 sm:p-6 max-w-screen-2xl mx-auto">
      {/* Package card (same) */}
      <div className="mb-6 bg-white rounded-3xl p-6 shadow-lg border border-gray-100">
        <div className="flex items-center gap-3 mb-4">
          <Shield className="w-7 h-7 text-green-600" />
          <h2 className="text-2xl font-bold text-gray-800">Current Package</h2>
        </div>
        {plan && (
          <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
            <div><p className="text-3xl font-bold text-gray-900">{plan.label}</p><p className="text-lg text-green-700 font-medium mt-1">ZMW {plan.monthly}<span className="text-gray-500 text-sm"> / month</span></p></div>
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                {subscriptionStatus === 'active' && <CheckCircle className="text-green-600" size={24} />}
                {subscriptionStatus === 'trialing' && <Clock className="text-blue-600" size={24} />}
                <span className="text-lg font-semibold">{subscriptionStatus === 'active' ? 'Active' : `Trial — ${trialDaysLeft} day${trialDaysLeft!==1?'s':''} left`}</span>
              </div>
              <button onClick={() => navigate('/app/settings')} className="bg-green-600 text-white px-6 py-3 rounded-xl font-semibold">Subscribe Now</button>
            </div>
          </div>
        )}
      </div>

      <div className="flex justify-end mb-4">
        <button onClick={fetchAllData} disabled={refreshing} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg">
          <RefreshCw size={16} className={refreshing ? 'animate-spin' : ''} /> {refreshing ? 'Refreshing...' : 'Refresh Data'}
        </button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-4 gap-4 sm:gap-6 mb-8">
        <div className="bg-white rounded-3xl p-6 shadow"><div className="flex justify-between"><div><p className="text-xs text-gray-500">Today's Sales</p><p className="text-2xl font-bold text-green-600">{currency} {todaySales.toFixed(2)}</p></div><DollarSign className="w-10 h-10 text-green-600"/></div></div>
        <div className="bg-white rounded-3xl p-6 shadow"><div className="flex justify-between"><div><p className="text-xs text-gray-500">This Month</p><p className="text-2xl font-bold">{currency} {monthSales.toFixed(2)}</p></div><TrendingUp className="w-10 h-10 text-blue-600"/></div></div>
        <div className="bg-white rounded-3xl p-6 shadow"><div className="flex justify-between"><div><p className="text-xs text-gray-500">Transactions</p><p className="text-2xl font-bold">{totalTransactions}</p></div><ShoppingCart className="w-10 h-10 text-purple-600"/></div></div>
        <div className="bg-white rounded-3xl p-6 shadow"><div className="flex justify-between"><div><p className="text-xs text-gray-500">Active Lay By</p><p className="text-2xl font-bold">{activeLaybyCount}</p></div><Package className="w-10 h-10 text-orange-600"/></div></div>
      </div>

      {/* Quick Access Buttons (same) */}
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4 mb-8">
        <button onClick={() => navigate('/app/pos')} className="bg-green-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2"><ShoppingCart className="w-8 h-8"/><span>POS</span></button>
        <button onClick={() => navigate('/app/inventory')} className="bg-blue-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2"><Package className="w-8 h-8"/><span>Inventory</span></button>
        <button onClick={() => navigate('/app/employees')} className="bg-purple-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2"><Users className="w-8 h-8"/><span>Employees</span></button>
        <button onClick={() => navigate('/app/discounts')} className="bg-amber-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2"><Percent className="w-8 h-8"/><span>Discounts</span></button>
        <button onClick={() => navigate('/app/layby')} className="bg-orange-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2"><Package className="w-8 h-8"/><span>Lay By</span></button>
        <button onClick={() => navigate('/app/invoices')} className="bg-teal-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2"><FileText className="w-8 h-8"/><span>Invoices</span></button>
        <button onClick={() => navigate('/app/sales')} className="bg-cyan-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2"><Receipt className="w-8 h-8"/><span>Sales</span></button>
        <button onClick={() => navigate('/app/reports')} className="bg-violet-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2"><BarChart3 className="w-8 h-8"/><span>Reports</span></button>
        <button onClick={() => navigate('/app/returns')} className="bg-red-600 text-white p-6 rounded-3xl flex flex-col items-center gap-2"><RotateCcw className="w-8 h-8"/><span>Returns</span></button>
      </div>

      {/* Low Stock & Expiring (same) */}
      <div className="bg-white rounded-3xl p-6 shadow mb-8">
        <div className="flex items-center gap-3 mb-4"><AlertOctagon className="w-6 h-6 text-orange-500"/><h2 className="font-semibold">Low Stock (&le; {lowStockThreshold})</h2></div>
        {lowStockProducts.length===0 ? <p className="text-gray-500 text-sm py-4">All products are well stocked.</p> : (
          <div className="space-y-4">{lowStockProducts.map(p=>(<div key={p.id} className="flex items-center justify-between py-2 border-b"><p className="font-medium">{p.name}</p><span className="px-3 py-1 text-xs font-medium rounded-full bg-orange-100 text-orange-700">{p.stock_quantity} left</span></div>))}</div>
        )}
      </div>

      <div className="bg-white rounded-3xl p-6 shadow mb-8">
        <div className="flex items-center gap-3 mb-4"><Clock className="w-6 h-6 text-red-500"/><h2 className="font-semibold">Products Expiring Soon</h2></div>
        {expiringProducts.length===0 ? <p className="text-gray-500 text-sm py-4">No products expiring within 7 days.</p> : (
          <div className="space-y-4">{expiringProducts.map(p=>(<div key={p.id} className="flex items-center justify-between py-2 border-b"><div><p className="font-medium">{p.name}</p><p className="text-xs text-gray-500">Expires {new Date(p.expiry_date).toLocaleDateString()}</p></div><div className="flex items-center gap-2"><span className="px-3 py-1 text-xs rounded-full">{p.daysLeft} days</span><button onClick={()=>handleAddDiscount(p)} className="text-xs bg-green-600 text-white px-4 py-2 rounded-xl">Add Discount</button></div></div>))}</div>
        )}
      </div>

      {/* Sales Trend (same) */}
      <div className="bg-white rounded-3xl p-6 shadow">
        <h2 className="text-xl font-semibold mb-4">Sales Trend (Last 7 Days)</h2>
        <ResponsiveContainer width="100%" height={320}>
          <LineChart data={salesChartData}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="day" />
            <YAxis />
            <Tooltip formatter={(value) => `K ${value}`} />
            <Line type="monotone" dataKey="sales" stroke="#10b981" strokeWidth={4} />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
